Algorithm prefixFunction(P)
{ m là độdài của P} 
p[0] = 0; i = 1; j = 0;
while i < m do 
begin 
while ( j > 0 && P[i] != P[j]) do
j = p[j];
if (P[i] = P[j]) then j = j + 1; 
p[i] = j; 
i = i + 1;
end.

