p Å prefixFunction(P);
j = 0; i = 0 ; 
while ( i < n) do 
begin 
while ( j >= 0 && T[i] != P[j]) do
j = p[j];
if (T[i] = P[j]) then j = j + 1; 
if (j = m ) then output(i-m);
i = i + 1;
end.
